  "pr.unver_pf": "अपलोड-पूर्वं पश्यतु: अस्य निर्माणसमये (14 Nov 2026) EPFO इत्यस्य स्वीयं फ़ाइल-संरचना-डॉक्यूमेंट उद्घाटयितुं न शक्तम्। 11 फ़ील्ड तेषां क्रमः च पेरोल-सॉफ़्टवेयर-निर्मातृभिः प्रकाशितम् अनुसरन्ति। फ़ाइल EPFO पोर्टलस्य ECR पृष्ठे अपलोड करोतु; यदि पोर्टलं पङ्क्तिं निरस्यति, कारणं वदति।",
