  "pr.esiintro": "मासस्य सैलरी स्लिप ESIC नियोक्तृ-पोर्टल-कृते मासिक-अंशदान-शीट चालान-राशीः च रचयन्ति। केवलं येषां वेतनं सीमायाम् अन्तः (अथवा ये तस्मिन् एव अर्धवर्षे पूर्वम् आवृताः), ते एव फ़ाइल-मध्ये सूच्यन्ते।",
  "pr.unver_esi": "इयं शीट ESIC पोर्टलस्य स्वीयं Monthly Contribution टेम्पलेट अनुसरति (15 Nov 2026 दिने जाँचितम्): षट् टेक्स्ट-कॉलमाः, Excel 97-2003 (.xls) रूपेण सेव कृता। अस्मिन् मासे वेतन-रहिताः कर्मचारिणः अपि रीज़न-कोड सह सूच्यन्ते। प्रथमं एकं मासम् अपलोड कृत्वा पोर्टलस्य परिणामं पश्यतु।",
