  "it.m_senior": "60 वर्षीयः अधिको वा निवासी यस्य व्यापार-प्रोफ़ेशन-आयः नास्ति, सः एडवांस टैक्स न ददाति (section 403(3))। रिटर्न फ़ाइल करणे शेषं ददातु।",
