  "it.basis": "एते आङ्काः कस्मिन् आधारिताः ({d} दिने)",
  "it.b1": "दराः ({d} दिने), टैक्स वर्ष 2026-27: न्यू रेजीम ₹4 लाख पर्यन्तं शून्यम्, ₹8 लाख पर्यन्तं 5%, ₹12 लाख पर्यन्तं 10%, ₹16 लाख पर्यन्तं 15%, ₹20 लाख पर्यन्तं 20%, ₹24 लाख पर्यन्तं 25%, ततः उपरि 30%; रिबेट येन ₹12 लाख पर्यन्तम् आयः टैक्सं न ददाति, किञ्चित् उपरि मार्जिनल रिलीफ च; वेतने स्टैंडर्ड डिडक्शन ₹75,000। ओल्ड रेजीम: ₹2.5 लाख पर्यन्तं शून्यम् (60 वयसि ₹3 लाख, 80 वयसि ₹5 लाख), ₹5 लाख पर्यन्तं 5%, ₹10 लाख पर्यन्तं 20%, ततः उपरि 30%; ₹5 लाख पर्यन्तं रिबेट ₹12,500; स्टैंडर्ड डिडक्शन ₹50,000। एते दराः सैलरी स्लिप टूल पूर्वमेव उपयुनक्ति; अस्मिन् बिल्डे Finance Act तः पुनः न पठिताः, अतः पश्यतु।",
  "it.b2": "एडवांस टैक्स (Income-tax Act 2025, sections 403 to 408): यदा TDS अनन्तरं टैक्स ₹10,000 अधिको वा तदा देयः; 15 June यावत् 15%, 15 September यावत् 45%, 15 December यावत् 75%, 15 March यावत् सर्वम्; प्रिज़म्प्टिव टैक्सपेयर 15 March यावत् सर्वं ददाति; 31 March यावत् पेमेंट अस्य वर्षस्य कृते गण्यते; व्यापार-आय-रहितः 60 वर्षीयः अधिको वा निवासी मुक्तः।",
  "it.b3": "ब्याज: section 424 (पुराणं 234B) यदा टैक्सस्य 90% तः न्यूनं दत्तं तदा न्यूनतायां प्रतिमासं मासांशं वा 1%; section 425 (पुराणं 234C) प्रथम-त्रि-किस्तीनां प्रत्येकस्याः न्यूनतायां 3% (यदि 15 June यावत् 12% 15 September यावत् 36% च दत्तं तर्हि नास्ति) March-न्यूनतायां 1% च।",
  "it.b4": "उपरि sections 15 Nov 2026 दिने Income Tax Department इत्यस्य वेबसाइट (incometaxindia.gov.in) उपरि आधिकारिक-पाठेन सह शब्दशः जाँचिताः। मुद्रितः Act निर्णयति।",
  "it.b5": "बुक-प्रॉफिट टैक्सेबल-प्रॉफिट न: Act अनुसारं डेप्रिसिएशन, अस्वीकृताः व्ययाः, प्रिज़म्प्टिव नियमाः च तं परिवर्तयन्ति। इमं प्लानं डेटा शीट च स्व-अकाउंटेंट प्रति ददातु।",
  "it.b6": "न गणितम्: सरचार्ज, विशेष-दरेषु कैपिटल गेन, विदेशी-टैक्स-रिलीफ, नाबालिगस्य आयस्य टैक्स, विलम्बित-फ़ाइलिंग-ब्याज च।",
  "it.b7": "किमपि फ़ाइल न क्रियते, खाता-पुस्तकेषु च किमपि न लिख्यते।",
  "it.itr_h": "कः रिटर्न फ़ॉर्मः उपयुक्तः, किमर्थं, के कागदाः सज्जाः रक्षणीयाः इति द्रष्टुं कतिचित् प्रश्नान् उत्तरयतु।",
