  "it.formd_ITR-1": "वेतन-पेंशन-युक्ताय निवासी-व्यक्तये, द्वे यावत् गृह-सम्पत्ती, ब्याज इव अन्य-स्रोताः, ₹50 लाख पर्यन्तं कुलायः च।",
  "it.formd_ITR-2": "व्यापार-प्रोफ़ेशन-आय-रहिताय व्यक्तये HUF वा, यस्य कैपिटल गेन, ₹50 लाख तः अधिकः आयः, द्वाभ्याम् अधिकाः गृह-सम्पत्तयः, विदेशी-सम्पत्तिः आयः वा, अथवा यः ITR-1 मध्ये न उपयुक्तः।",
  "it.formd_ITR-3": "प्रिज़म्प्टिव स्कीम-अन्तर्गतं न विद्यमानेन व्यापार-प्रोफ़ेशन-आयेन युक्ताय व्यक्तये HUF वा, फर्मस्य पार्टनराय, अथवा ITR-4 मध्ये अनुपयुक्ताय कस्मैचित्।",
  "it.formd_ITR-4": "प्रिज़म्प्टिव व्यापार-आय-युक्ताय निवासी-व्यक्तये HUF वा, ₹50 लाख पर्यन्तं कुलायः, वेतनं पेंशन वा, द्वे यावत् गृह-सम्पत्ती, अन्य-स्रोताः च।",
