  "it.w_pres": "सरल-अन्य-आयेन सह प्रिज़म्प्टिव व्यापार-आयः ITR-4 मध्ये उपयुक्तः।",
  "it.w_simple": "केवलं वेतनं, गृह-सम्पत्तिः, ब्याज च, सीमासु अन्तः, ITR-1 मध्ये उपयुक्तम्।",
  "it.n_forms": "शर्ताः 31 March 2026 दिने समाप्त-वर्षाय अधिसूचितान् रिटर्नान् अनुसरन्ति (टैक्स-पोर्टलानुसारं ITR-1 ITR-4 च इदानीं द्वे यावत् गृह-सम्पत्ती अनुमन्येते)। टैक्स वर्ष 2026-27 कृते रिटर्न Income-tax Rules, 2026 अन्तर्गतम् अद्यापि अधिसूचनीयाः: फ़ाइल-पूर्वं फ़ॉर्मस्य स्वीयां “के उपयोक्तुं न शक्नुवन्ति” सूचीं पठतु।",
  "it.n_ltcg": "लिस्टेड-शेयर-इक्विटी-फंडेषु लघु-लॉन्ग-टर्म-गेन केषुचित् वर्षेषु ITR-1 ITR-4 मध्ये अनुमताः आसन्; 2026-27 कृते इदं न पुष्टम्, अतः ITR-2 सुरक्षितः विकल्पः, फ़ॉर्मस्य स्वीया सूची निर्णयति।",
  "it.n_ae": "Section 44AE (माल-वाहनम्) इत्यस्य स्वीयाः शर्ताः सन्ति; प्रिज़म्प्टिव फ़ॉर्म-उपयोगात् पूर्वं ताः पश्यतु।",
