  "ca.intro": "एकं व्यापारम् एकाम् अवधिं च एकस्यां केवल-पठन-फ़ाइल (.nsca) मध्ये संगृह्णाति। स्व-अकाउंटेंट प्रति WhatsApp ईमेल वा द्वारा प्रेषयतु। ते ताम् ca.niveshsahayak.in उपरि उद्घाटयन्ति, खाता-पुस्तकानि पठन्ति, प्रश्नान् योजयन्ति, टिप्पणीः भवते प्रतिप्रेषयन्ति च।",
  "ca.notlive": "इदं फ़ाइल-हस्तान्तरणम्, न तु लाइव साझा लॉगिन। भवतः अकाउंटेंट खाता-पुस्तकानि यथा फ़ाइल-रचना-समये आसन् तथा पश्यति। लाइव लॉगिन कृते भवतः खाता-पुस्तकानि रक्षन् सर्वर आवश्यकः, Nivesh Sahayak इत्यस्य सर्वर नास्ति: भवतः खाता-पुस्तकानि भवतः डिवाइसे तिष्ठन्ति। नूतनानां एंट्रीनां कृते नूतनां फ़ाइल रचयतु।",
  "ca.what": "किं गच्छति",
  "ca.earlier": "प्रथम-दिनाङ्कात् पूर्वम् एंट्री अपि (ओपनिंग बैलेंस एजिंग च कृते आवश्यकाः)",
  "ca.items": "क्रय-विक्रय-दर-सहिता आइटम-सूची (स्टॉक कृते आवश्यकी)",
