  "ca.cT": "CA कमेंट",
  "ca.cIntro": "भवतः अकाउंटेंट प्रश्नानां टिप्पणीनां च लघु-फ़ाइल (.nsca-comments) प्रतिप्रेषयति। प्रत्येकं प्रश्नं तस्य एंट्री-पार्श्वे द्रष्टुम् अत्र लोड करोतु। उत्तरं ददातु, पिहितम् इति चिह्नयतु, प्रतिप्रेषणाय फ़ाइल पुनः सेव करोतु।",
