  "ca.general": "सामान्यः कमेंट",
  "cv.h1": "अकाउंटेंट व्यूअर: क्लाइंटेन प्रेषितां खाता-पुस्तक-फ़ाइल उद्घाटयतु",
  "cv.intro": "भवतः क्लाइंट एकस्याः अवधेः खाता-पुस्तकानि एकस्यां फ़ाइल मध्ये संगृह्य WhatsApp ईमेल वा द्वारा भवते प्रेषयति। अत्र ताम् उद्घाट्य पठतु: शेषदेयम्, पक्षाः, लेजर, डे बुक, GST गणना, फ़ाइनल अकाउंट, प्रत्येकं डॉक्यूमेंट च। अन्विष्यतु फ़िल्टर करोतु च, कस्मिन्नपि एंट्री-मध्ये प्रश्नं पृच्छतु, कमेंट च लघु-फ़ाइल-रूपेण प्रतिप्रेषयतु। निःशुल्कम्, लॉगिन नास्ति, किमपि अपलोड न भवति: फ़ाइल भवतः ब्राउज़रे एव पठ्यते।",
  "cv.drop": ".nsca फ़ाइल अत्र स्थापयतु",
  "cv.choose": "फ़ाइल चिनोतु",
  "cv.dropnote": "फ़ाइल अस्मिन् डिवाइसे तिष्ठति। अत्र किमपि सेव न भवति, क्लाइंटस्य खाता-पुस्तकानि अत्रतः परिवर्तयितुं न शक्नोति।",
  "cv.nav.home": "आरम्भः",
  "cv.docs": "डॉक्यूमेंट",
  "cv.day": "डे बुक",
  "cv.fin": "फ़ाइनल अकाउंट",
  "cv.gst": "GST गणना",
  "cv.cT": "प्रश्नाः कमेंट च",
  "cv.how.h": "इदं कथं चलति",
  "cv.how.1": "भवतः क्लाइंट Nivesh Sahayak उद्घाट्य “मम डेटा” › “अकाउंटेंट प्रति प्रेषयतु” गत्वा एकस्य व्यापारस्य अवधेः च कृते \"मम अकाउंटेंट कृते फ़ाइल रचयतु\" चिनोति।",
  "cv.how.2": "ते भवते फ़ाइल (.nsca अन्ता) तस्मिन् एव सन्देशे लघु चेक कोड च प्रेषयन्ति।",
  "cv.how.3": "भवान् फ़ाइल अस्मिन् पृष्ठे उद्घाटयति। पृष्ठं फ़ाइल अपरिवर्तिता वा इति वदति, क्लाइंटेन दत्तं चेक कोड लिखित्वा तुलनां करोति च।",
  "cv.how.4": "खाता-पुस्तकानि पठतु, अन्विष्यतु, कस्मिन्नपि डॉक्यूमेंटे डे-बुक-एंट्री-मध्ये स्क्रीने वा \"प्रश्नं कमेंट वा योजयतु\" नुदतु। भवता लिखितं सर्वम् अस्मिन् ब्राउज़रे तिष्ठति।",
  "cv.how.5": "समाप्ते \"प्रश्नाः कमेंट च\" उद्घाट्य लघु .nsca-comments फ़ाइल प्रतिप्रेषयतु। क्लाइंट तां लोड कृत्वा प्रत्येकं प्रश्नं एंट्री-पार्श्वे पश्यति। ते उत्तरं दातुं शक्नुवन्ति, भवान् उत्तराणि अत्र लोड कर्तुं शक्नोति।",
  "cv.live.h": "फ़ाइल-हस्तान्तरणम्, न लाइव लॉगिन",
  "cv.live.p": "इदं फ़ाइल-हस्तान्तरणम्। भवान् क्लाइंटस्य खाते लॉगिन न करोति, ते अनन्तरं कृतानि परिवर्तनानि न पश्यति। लाइव साझा लॉगिन कृते खाता-पुस्तकानि रक्षन् सर्वर आवश्यकः, Nivesh Sahayak इत्यस्य सर्वर नास्ति: खाता-पुस्तकानि क्लाइंटस्य डिवाइसे तिष्ठन्ति। नूतनाय अवधये सुधारानन्तरं वा, क्लाइंटं नूतनां फ़ाइल याचतु।",
  "cv.safe.h": "फ़ाइल-मध्ये किम् अस्ति, किं नास्ति",
  "cv.safe.p": "भवतः क्लाइंट यत् गच्छति तत् चिह्नयति। डिफ़ॉल्ट-रूपेण फ़ाइल-मध्ये एकस्य व्यापारस्य अवधि-अन्तं यावत् एंट्री, पक्षाः, आइटम च सन्ति। कोटेशन ऑर्डर च, वेतन-स्टाफ-रिकॉर्ड, फ़ोन नंबर ईमेल पता च, व्यापारस्य बैंक-खाता-विवरणं च यावत् क्लाइंट न चिह्नयति तावत् त्यज्यन्ते। चित्राणि, PIN, बैकअप-सेटिंग च कदापि न अन्तर्भवन्ति। फ़ाइल चेकसम वहति येन किमपि परिवर्तनम् अस्मिन् पृष्ठे दृश्यते। यः फ़ाइल परिवर्त्य चेकसम पुनः गणयति, तं चेकसम निरोद्धुं न शक्नोति, अतः चेक कोड क्लाइंटेन पृथक् प्रेषितेन सह तुलयतु।",
  "cv.readonly": "इयं फ़ाइलस्य केवल-पठन-दृष्टिः: अत्र किमपि परिवर्तयितुं सेव कर्तुं वा न शक्यते।",
  "cv.notfile": "इयं Nivesh Sahayak अकाउंटेंट फ़ाइल (.nsca) नास्ति।",
  "cv.iscomments": "इयं कमेंट फ़ाइल। प्रथमं खाता-पुस्तक-फ़ाइल (.nsca) उद्घाटयतु, ततः \"प्रश्नाः कमेंट च\" तः कमेंट लोड करोतु।",
