  "hm.h.recv": "प्राप्य-दिनानि",
  "hm.h.recv.how": "ग्राहकाणां {r} देयम्। भवान् प्रतिदिनं प्रायः {d} विक्रीणाति, अतः बिलं प्रत्यागन्तुं प्रायः {n} दिनानि लगन्ति।",
  "hm.h.recv.good": "धनं शीघ्रं प्रत्यागच्छति। मन्दान् स्मारयतु।",
  "hm.h.recv.ok": "धनं मन्दं प्रत्यागच्छति। शेषदेय-स्क्रीनात् प्रतिसप्ताहं स्मरणं प्रेषयतु।",
  "hm.h.recv.low": "धनं ग्राहकेषु अतिदीर्घं रुद्धम्। प्राचीनतमानि बिलानि प्रथमं संगृह्णातु, नूतन-ऑर्डरात् पूर्वम् आंशिक-पेमेंट याचतु।",
  "hm.h.recv.rule": "ग्राहकाणाम् अद्यापि देयं धनं गत-3-पूर्णमासानां दैनिक-विक्रयेण विभक्तम्। 30 दिनानि न्यूनानि वा = 100, 90 दिनानि अधिकानि वा = 0।",
