  "hm.h.margin.how1": "गत-3-मासेषु विक्रीत-प्रत्येक-100 मध्ये क्रय-व्ययानन्तरं {p} शेषम्।",
  "hm.h.margin.good": "स्वस्थः भागः शेषः। मूल्य-परिवर्तने तं रक्षतु।",
  "hm.h.margin.ok": "मार्जिन अल्पं पतत् वा। विक्रय-मूल्यानि मुख्य-आइटमानां लागतं च पश्यतु।",
  "hm.h.margin.low": "प्रायः किमपि न शेषम्। मूल्यं वर्धयतु, लागतं न्यूनयतु, अथवा हानिकर-आइटमानां विक्रयं स्थगयतु।",
  "hm.h.margin.rule": "गत-3-पूर्णमासानां विक्रयः न्यूनं क्रय-व्ययाः, विक्रयस्य भागरूपेण। 15 अधिकं वा = 100, 0 न्यूनं वा = 0; पूर्व-3-मासैः तुलया 5 अङ्केभ्यः अधिकं पतिते 20 अङ्काः न्यूनीक्रियन्ते। हस्ते स्टॉक न गण्यते।",
  "hm.h.creep": "व्यय-वृद्धिः",
  "hm.h.creep.how": "गतमासे भवतः व्ययाः {l} आसन्; ततः पूर्वं 3 मासानां सरासरी {a}। इदं {p}% परिवर्तनम्।",
  "hm.h.creep.good": "व्ययाः स्थिराः।",
  "hm.h.creep.ok": "व्ययाः वर्धन्ते। रिपोर्ट-स्क्रीने किं शीर्षकं वृद्धम् इति पश्यतु।",
  "hm.h.creep.low": "व्ययाः उत्प्लुताः। वृद्धं शीर्षकं अन्विष्य तत् एकवारस्य बिलं न इति पश्यतु।",
  "hm.h.creep.rule": "गत-पूर्णमासस्य व्ययाः ततः पूर्व-3-मासानां सरासर्या सह। 5% पर्यन्तं वृद्धिः = 100, 40% अधिका वा = 0। एकवारस्य बृहत्-बिलं मासं यावत् तं न्यूनयति।",
  "hm.rm.t": "अस्मिन् डिवाइसे स्मरणानि",
  "hm.rm.p": "App उद्घाटने अद्य किम् आवश्यकम् इति दर्शयति। अत्यावश्यक-पङ्क्तीनां कृते प्रतिदिनम् एकवारं फ़ोन-नोटिफ़िकेशन अपि दर्शयितुं शक्नोति।",
