  "hm.rm.nosupport": "अयं ब्राउज़र नोटिफ़िकेशन न समर्थयति। “मम दिनम्” सूची तु चलति।",
  "hm.rm.denied": "अस्याः साइटस्य नोटिफ़िकेशन अवरुद्धाः। ब्राउज़रस्य साइट-सेटिंग मध्ये अनुमतिं दत्त्वा पुनः चिह्नयतु।",
