  "hm.rm.set": "नोटिफ़िकेशन चालूः। App उद्घाटने अत्यावश्यक-पङ्क्तयः दृश्यन्ते।",
  "hm.rm.title": "{b}: अद्य भवतः आवश्यकता",
  "hm.rm.ics": "देय-दिनाङ्कान् फ़ोन-कैलेंडरे स्थापयतु",
  "hm.rm.icsp": "अग्रिम-60-दिनानां कैलेंडर-फ़ाइल रचयति: बिल-देय-दिनाङ्काः टैक्स-दिनाङ्काः च। स्वकैलेंडरे योजयितुं फ़ोने उद्घाटयतु, यत् App बन्दे सति अपि एकदिनपूर्वं स्वयं घण्टां वादयति।",
