  "hm.rm.lim": "ब्राउज़रः किं कर्तुं न शक्नोति",
  "hm.rm.l1": "वेब-पृष्ठं बन्दे सति न चलति, अस्य App पृष्ठे पुश-सन्देश-प्रेषणाय सर्वर नास्ति। अतः App-स्मरणं केवलं App उद्घाटने दृश्यते।",
  "hm.rm.l2": "सर्वं भवतः डिवाइसे गण्यते, अतः इंटरनेट विना चलति। भवतः व्यापार-विषये किमपि कुत्रापि न प्रेष्यते।",
  "hm.rm.l3": "अविस्मरणीय-दिनाङ्कानां कृते कैलेंडर फ़ाइल उपयुनक्तु: भवतः फ़ोन-कैलेंडरं स्वयं घण्टां वादयति। सा अद्यतन-स्थितेः प्रतिलिपिः, अतः नूतन-बिल-लेखनानन्तरं नूतनां फ़ाइल रचयतु।",
  "hm.rm.l4": "इन्स्टॉल कृते App मध्ये तस्य आइकन-उपरि अङ्कः अत्यावश्यक-विषयाणां सङ्ख्यां दर्शयति, यत्र भवतः फ़ोनम् अनुमन्यते।",
